sys_transform_script.script:
(function runTransformScript(source, map, log, target /*undefined onStart*/ ) {

	var gr = new GlideRecord(target.getTableName());

	// Set skip to true if a matching row exists
    var gr_is_row = new GlideRecord(source.getTableName());
    gr_is_row.addQuery("sys_import_set", import_set.sys_id);
	gr_is_row.addQuery("u_skip", false);
    gr_is_row.query();
    while (gr_is_row.hasNext()) {
        gr_is_row.next();

		gr.addQuery("serial_number", gr_is_row.getValue("u_serial_number"));
		gr.addQuery("asset_tag", gr_is_row.getValue("u_asset_tag"));
		gr.addQuery("model", gr_is_row.getValue("u_model"));
		gr.addQuery("location", gr_is_row.getValue("u_location"));
		gr.setLimit(1);
		gr.query();
		if(gr.next()) {
			gr_is_row.setValue("u_skip", true);
			gr_is_row.setValue("u_skip_reason", "Matching target row found");
			gr_is_row.update();
		}

	}

})(source, map, log, target);
